import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import './Auth.css';

const Login = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [role, setRole] = useState('student');
  const [error, setError] = useState('');
  const { login } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = (e) => {
    e.preventDefault();
    setError('');

    try {
      const user = login(email, password, role);
      
      // Redirect based on role
      switch (user.role) {
        case 'admin':
          navigate('/admin');
          break;
        case 'professor':
          navigate('/professor');
          break;
        case 'student':
          navigate('/student');
          break;
        default:
          navigate('/');
      }
    } catch (error) {
      setError('Erreur de connexion. Veuillez vérifier vos informations.');
    }
  };

  return (
    <div className="main-content">
      <div className="auth-container">
        <div className="sidebar">
          <div className="logo-container">
            <img src="/api/placeholder/40/40" alt="QGen Logo" className="logo-img" />
            <h1>QGen</h1>
          </div>
          
          <div className="slogan-container">
            <h2>Un sujet, un quiz.<br/>C'est tout!</h2>
            <p className="subtitle">Votre assistant pour créer des quiz simples, rapides et efficaces.</p>
          </div>
        </div>
        
        <div className="form-section">
          <h1 className="welcome-title">BIENVENUE</h1>
          
          <div className="form-box">
            <h2 className="form-title">CONNEXION</h2>
            
            {error && <div className="error-message">{error}</div>}
            
            <form onSubmit={handleSubmit} className="login-form">
              <div className="input-group">
                <div className="input-with-icon">
                  <span className="icon">✉️</span>
                  <input
                    type="email"
                    placeholder="Email"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    required
                  />
                </div>
              </div>
              
              <div className="input-group">
                <div className="input-with-icon">
                  <span className="icon">🔒</span>
                  <input
                    type="password"
                    placeholder="Mot de passe"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    required
                  />
                </div>
              </div>
              
              <div className="input-group">
                <select
                  value={role}
                  onChange={(e) => setRole(e.target.value)}
                  className="role-select"
                >
                  <option value="student">Étudiant</option>
                  <option value="professor">Professeur</option>
                  <option value="admin">Administrateur</option>
                </select>
              </div>
              
              <button type="submit" className="submit-button">Se connecter</button>
            </form>
            
            <div className="alternate-login">
              <p>Continuer avec:</p>
              <button className="google-button">
                <img src="/api/placeholder/20/20" alt="Google" /> Continuer avec Google
              </button>
            </div>
            
            <div className="register-link">
              <Link to="/register">S'inscrire</Link>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;
